CREATE TABLE `custom_form_fields` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `form_id` int(11) NOT NULL,
  `section_title` varchar(150) NOT NULL DEFAULT 'General Information',
  `field_key` varchar(100) NOT NULL,
  `field_label` varchar(255) NOT NULL,
  `field_type` varchar(50) NOT NULL COMMENT 'text, number, email, textarea, select, radio, checkbox, file, date, datetime, heading',
  `placeholder` varchar(255) DEFAULT NULL,
  `default_value` text DEFAULT NULL,
  `help_text` varchar(255) DEFAULT NULL,
  `is_required` tinyint(1) NOT NULL DEFAULT 0,
  `options_json` longtext DEFAULT NULL COMMENT 'JSON array of options for select, radio, checkbox',
  `validation_rules_json` longtext DEFAULT NULL COMMENT 'JSON object for file extensions, max size, min, max, regex',
  `grid_width` int(11) NOT NULL DEFAULT 12 COMMENT '12=full, 6=half, 4=third, 3=quarter',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_cff_form_id` (`form_id`),
  KEY `idx_cff_sort` (`sort_order`),
  KEY `idx_cff_status` (`status`),
  CONSTRAINT `fk_cff_form` FOREIGN KEY (`form_id`) REFERENCES `custom_forms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=469 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
